public str getName()
{
    return fieldPName(EcoResProductCategory, DisplayOrder);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Real);
    EcoResProductCategory ecoResProductCategory;
    while select DisplayOrder from ecoResProductCategory
        group by DisplayOrder
